PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS mi_candle(id INTEGER PRIMARY KEY AUTOINCREMENT,symbol TEXT NOT NULL,timeframe TEXT NOT NULL,open_time TEXT NOT NULL,close_time TEXT NOT NULL,open REAL NOT NULL,high REAL NOT NULL,low REAL NOT NULL,close REAL NOT NULL,tick_volume INTEGER NOT NULL DEFAULT 0,spread REAL NOT NULL DEFAULT 0,source TEXT NOT NULL DEFAULT 'MT5',is_closed INTEGER NOT NULL DEFAULT 1 CHECK(is_closed IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(symbol,timeframe,open_time));
CREATE INDEX IF NOT EXISTS ix_mi_candle_lookup ON mi_candle(symbol,timeframe,open_time DESC);
CREATE TABLE IF NOT EXISTS mi_data_quality(id INTEGER PRIMARY KEY AUTOINCREMENT,symbol TEXT NOT NULL,timeframe TEXT NOT NULL,state TEXT NOT NULL,last_closed_at TEXT,age_seconds REAL,missing_bars INTEGER NOT NULL DEFAULT 0,reason TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(symbol,timeframe));
CREATE TABLE IF NOT EXISTS mi_strength_snapshot(id INTEGER PRIMARY KEY AUTOINCREMENT,currency TEXT NOT NULL,timeframe TEXT NOT NULL,as_of TEXT NOT NULL,value REAL NOT NULL,slope REAL NOT NULL DEFAULT 0,velocity REAL NOT NULL DEFAULT 0,acceleration REAL NOT NULL DEFAULT 0,persistence REAL NOT NULL DEFAULT 0,confidence REAL NOT NULL DEFAULT 0,sample_count INTEGER NOT NULL DEFAULT 0,quality TEXT NOT NULL DEFAULT 'FRESH',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(currency,timeframe,as_of));
CREATE INDEX IF NOT EXISTS ix_mi_strength_latest ON mi_strength_snapshot(currency,timeframe,as_of DESC);
CREATE TABLE IF NOT EXISTS mi_relationship_snapshot(id INTEGER PRIMARY KEY AUTOINCREMENT,pair TEXT NOT NULL,timeframe TEXT NOT NULL,as_of TEXT NOT NULL,base_value REAL NOT NULL,quote_value REAL NOT NULL,gap REAL NOT NULL,abs_gap REAL NOT NULL,gap_velocity REAL NOT NULL DEFAULT 0,gap_acceleration REAL NOT NULL DEFAULT 0,persistence REAL NOT NULL DEFAULT 0,state TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0,inspection_priority TEXT NOT NULL DEFAULT 'NORMAL',reason_codes TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(pair,timeframe,as_of));
CREATE INDEX IF NOT EXISTS ix_mi_relationship_latest ON mi_relationship_snapshot(pair,timeframe,as_of DESC);
CREATE INDEX IF NOT EXISTS ix_mi_relationship_state ON mi_relationship_snapshot(state,inspection_priority,as_of DESC);
CREATE TABLE IF NOT EXISTS mi_calculation_run(id TEXT PRIMARY KEY,tenant_id TEXT,timeframe TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT,status TEXT NOT NULL,pair_count INTEGER NOT NULL DEFAULT 0,currency_count INTEGER NOT NULL DEFAULT 0,error TEXT,metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mi_ingestion_checkpoint(symbol TEXT NOT NULL,timeframe TEXT NOT NULL,last_open_time TEXT,last_close_time TEXT,last_sync_at TEXT,status TEXT NOT NULL DEFAULT 'PENDING',error TEXT,PRIMARY KEY(symbol,timeframe));
